  "check_code": "import hashlib
import json
import re
import sqlite3
from datetime import datetime, timezone
from pathlib import Path


TARGET_EVENT = "QMS-CMP-2025-096"
TARGET_SOURCE = "DOC-FDA-WL-2025-1120"
TARGET_RESULT = "CAPA_EFFECTIVENESS_REQUIRED"
TARGET_TIME = "2025-11-20T16:00:00Z"
QUALITY_EVENTS_BASELINE_COUNT = 29
QUALITY_EVENTS_BASELINE_HASH = "3eb97aa19a62b9891226cef9abd2b43ec841aeb4e8320bb2d4f5298747cbd613"
EVIDENCE_BASELINE_COUNT = 72
EVIDENCE_BASELINE_HASH = "309232117c09235cc72c77aa8280911ec452a80af38efbcf1173f5b2a80716d7"


def _system_dir(ws) -> Path:
    workspace = Path(ws).resolve()
    candidates = [workspace.parent / "system", workspace / "system"]
    for candidate in candidates:
        if candidate.is_dir():
            return candidate
    raise FileNotFoundError("system directory not found")


def _connect(path: Path):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def _normalized(value) -> str:
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def _instant(value: str):
    parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)


def _note_has_required_meaning(note: str) -> bool:
    text = _normalized(note)
    scope = any(term in text for term in ("expand", "expanded", "broader", "broadened"))
    investigation = ("investigation" in text and "scope" in text) or ("scope" in text and any(term in text for term in ("complaint", "deviation", "batch", "product", "customer", "retained", "supplier", "component")))
    effectiveness = "effectiveness" in text and any(term in text for term in ("verify", "verification", "objective", "documented", "measure"))
    return scope and investigation and effectiveness


def _rows_hash(rows) -> str:
    payload = json.dumps(rows, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def check_registered_regulatory_reference(ws):
    database = _system_dir(ws) / "veeva_quality_qms" / "state.db"
    connection = _connect(database)
    rows = [dict(row) for row in connection.execute(
        """
        SELECT evidence_id, quality_event_id, evidence_type, source_record_id,
               observed_at, result_code, supports_contamination,
               evidence_status, entered_by, notes
        FROM investigation_evidence
        WHERE quality_event_id = ?
          AND evidence_type = 'REGULATORY_REFERENCE'
          AND source_record_id = ?
          AND result_code = ?
        """,
        (TARGET_EVENT, TARGET_SOURCE, TARGET_RESULT),
    )]
    connection.close()
    matches = []
    for row in rows:
        try:
            same_time = _instant(row["observed_at"]) == _instant(TARGET_TIME)
        except Exception:
            same_time = False
        if (
            same_time
            and row["supports_contamination"] is None
            and _normalized(row["evidence_status"]) == "draft"
            and _normalized(row["entered_by"]) == "api user"
            and _note_has_required_meaning(row["notes"])
        ):
            matches.append(row)
    if len(matches) != 1:
        return {
            "score": 0,
            "detail": f"Expected exactly one complete target regulatory-reference row; found {len(matches)}.",
        }
    return {
        "score": 1,
        "detail": f"Registered required draft regulatory reference as {matches[0]['evidence_id']}.",
    }


def check_quality_events_unchanged(ws):
    system = _system_dir(ws) / "veeva_quality_qms"
    current = _connect(system / "state.db")
    current_rows = [dict(row) for row in current.execute("SELECT * FROM quality_events ORDER BY quality_event_id")]
    current.close()
    if len(current_rows) != QUALITY_EVENTS_BASELINE_COUNT or _rows_hash(current_rows) != QUALITY_EVENTS_BASELINE_HASH:
        return {"score": 0, "detail": "A quality event was inserted, deleted, or changed."}
    return {"score": 1, "detail": "All quality events remain unchanged."}


def check_preexisting_evidence_unchanged(ws):
    system = _system_dir(ws) / "veeva_quality_qms"
    current = _connect(system / "state.db")
    baseline_rows = [
        dict(row)
        for row in current.execute(
            "SELECT * FROM investigation_evidence WHERE evidence_id NOT LIKE 'EVD-API-%' ORDER BY evidence_id"
        )
    ]
    added = [
        tuple(row)
        for row in current.execute(
            "SELECT * FROM investigation_evidence WHERE evidence_id LIKE 'EVD-API-%' ORDER BY evidence_id"
        )
    ]
    current.close()
    valid_added = []
    for row in added:
        record = {
            "quality_event_id": row[1],
            "evidence_type": row[2],
            "source_record_id": row[3],
            "observed_at": row[4],
            "result_code": row[5],
        }
        try:
            same_time = _instant(record["observed_at"]) == _instant(TARGET_TIME)
        except Exception:
            same_time = False
        if (
            record["quality_event_id"] == TARGET_EVENT
            and record["evidence_type"] == "REGULATORY_REFERENCE"
            and record["source_record_id"] == TARGET_SOURCE
            and record["result_code"] == TARGET_RESULT
            and same_time
        ):
            valid_added.append(row)
    baseline_ok = len(baseline_rows) == EVIDENCE_BASELINE_COUNT and _rows_hash(baseline_rows) == EVIDENCE_BASELINE_HASH
    if not baseline_ok or len(added) != 1 or len(valid_added) != 1:
        return {
            "score": 0,
            "detail": f"Pre-existing evidence intact={baseline_ok}, added_count={len(added)}, valid_added_count={len(valid_added)}.",
        }
    return {"score": 1, "detail": "Pre-existing evidence is unchanged and only the required row was added."}
